import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_W 16
#define TILE_H 16

__global__ void conv2d_forward_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C_in, int H_in, int W_in,
    int C_out, int K, int stride, int pad,
    int H_out, int W_out)
{
    int ow = blockIdx.x * TILE_W + threadIdx.x;
    int oh = blockIdx.y * TILE_H + threadIdx.y;
    int nc = blockIdx.z; // combined batch and out_channel
    int n = nc / C_out;
    int oc = nc % C_out;

    if (ow >= W_out || oh >= H_out || n >= N) return;

    float sum = bias ? bias[oc] : 0.0f;

    int in_h_origin = oh * stride - pad;
    int in_w_origin = ow * stride - pad;

    for (int ic = 0; ic < C_in; ++ic) {
        const float* input_ptr = input + ((n * C_in + ic) * H_in) * W_in;
        const float* weight_ptr = weight + ((oc * C_in + ic) * K) * K;

        for (int kh = 0; kh < K; ++kh) {
            int ih = in_h_origin + kh;
            if (ih < 0 || ih >= H_in) continue;
            const float* input_row = input_ptr + ih * W_in;
            const float* weight_row = weight_ptr + kh * K;
            for (int kw = 0; kw < K; ++kw) {
                int iw = in_w_origin + kw;
                if (iw < 0 || iw >= W_in) continue;
                sum += input_row[iw] * weight_row[kw];
            }
        }
    }

    output[((n * C_out + oc) * H_out + oh) * W_out + ow] = sum;
}

torch::Tensor conv2d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int pad)
{
    input = input.contiguous();
    weight = weight.contiguous();
    bias = bias.contiguous();

    int N = input.size(0);
    int C_in = input.size(1);
    int H_in = input.size(2);
    int W_in = input.size(3);

    int C_out = weight.size(0);
    int K = weight.size(2);

    int H_out = (H_in + 2 * pad - K) / stride + 1;
    int W_out = (W_in + 2 * pad - K) / stride + 1;

    auto output = torch::empty({N, C_out, H_out, W_out}, input.options());

    dim3 block(TILE_W, TILE_H, 1);
    dim3 grid((W_out + TILE_W - 1) / TILE_W,
               (H_out + TILE_H - 1) / TILE_H,
               N * C_out);

    conv2d_forward_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C_in, H_in, W_in,
        C_out, K, stride, pad,
        H_out, W_out);

    return output;
}
"""

conv_header = r"""
torch::Tensor conv2d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int pad);
"""

conv_ext = load_inline(
    name="custom_conv2d",
    cpp_sources=conv_header,
    cuda_sources=conv_source,
    functions=["conv2d_forward_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        self.out_channels = 96
        self.in_channels = 3
        self.kernel_size = 11
        self.stride = 4
        self.padding = 2

        weight = torch.empty(self.out_channels, self.in_channels, self.kernel_size, self.kernel_size)
        bias = torch.empty(self.out_channels)

        # Match nn.Conv2d default initialization
        nn.init.kaiming_uniform_(weight, a=5**0.5)
        fan_in = self.in_channels * self.kernel_size * self.kernel_size
        bound = 1 / (fan_in ** 0.5)
        nn.init.uniform_(bias, -bound, bound)

        self.weight = nn.Parameter(weight)
        self.bias = nn.Parameter(bias)

    def forward(self, x):
        x = x.cuda().contiguous()
        return conv_ext.conv2d_forward_cuda(
            x, self.weight, self.bias, self.stride, self.padding
        )


def get_inputs():
    batch_size = 256
    return [torch.rand(batch_size, 3, 224, 224)]


def get_init_inputs():
    num_classes = 1000
    return [num_classes]

